const motorVisual = document.getElementById('motor-visual');
        const statusText = document.getElementById('status-text');
        const wave1 = document.getElementById('wave-1');
        const wave2 = document.getElementById('wave-2');
        const deviceStatus = document.getElementById('device-status');
        let gamepadIndex = null;
        let isVibrating = false;
        // --- INIT CHECKS ---
        window.addEventListener('load', () => {
            // Check Vibration API
            const vibSupported = "vibrate" in navigator;
            document.getElementById('spec-vib-api').innerHTML = vibSupported ?
                '<span class="text-emerald-500">Active</span>' :
                '<span class="text-slate-400">Unsupported</span>';
            // Check Gamepad API
            const gpSupported = "getGamepads" in navigator;
            document.getElementById('spec-gamepad-api').innerHTML = gpSupported ?
                '<span class="text-emerald-500">Active</span>' :
                '<span class="text-slate-400">Unsupported</span>';
            // Initial Status
            if (vibSupported && /Mobi|Android/i.test(navigator.userAgent)) {
                updateHardwareStatus("Mobile Motor Ready", "bg-emerald-500");
            } else if (gpSupported) {
                updateHardwareStatus("Waiting for Controller...", "bg-amber-500 animate-pulse");
                window.addEventListener("gamepadconnected", (e) => {
                    gamepadIndex = e.gamepad.index;
                    updateHardwareStatus("Gamepad Connected", "bg-emerald-500");
                    console.log("Gamepad connected:", e.gamepad);
                });
                window.addEventListener("gamepaddisconnected", () => {
                    gamepadIndex = null;
                    updateHardwareStatus("Gamepad Disconnected", "bg-amber-500");
                });
            } else {
                updateHardwareStatus("No Hardware Found", "bg-red-500");
            }
        });
        function updateHardwareStatus(msg, colorClass) {
            deviceStatus.innerHTML = `
                <div class="w-2.5 h-2.5 rounded-full ${colorClass}"></div>
                <span class="text-[9px] font-bold text-slate-500 uppercase tracking-tighter">${msg}</span>
            `;
        }
        // --- CORE LOGIC ---
        function animateVisual(duration) {
            motorVisual.classList.add('active');
            statusText.innerText = "VIBRATION ACTIVE";
            statusText.classList.add('text-rose-500', 'animate-pulse');
            // Trigger shockwaves
            wave1.classList.remove('animate');
            void wave1.offsetWidth; // trigger reflow
            wave1.classList.add('animate');
            setTimeout(() => {
                wave2.classList.remove('animate');
                void wave2.offsetWidth;
                wave2.classList.add('animate');
            }, 150);
            setTimeout(() => {
                motorVisual.classList.remove('active');
                statusText.innerText = "System Idle";
                statusText.classList.remove('text-rose-500', 'animate-pulse');
            }, duration);
        }
        function vibrateLogic(pattern) {
            // Mobile Vibration API
            if ("vibrate" in navigator) {
                navigator.vibrate(pattern);
            }
            // Gamepad Vibration
            if (gamepadIndex !== null) {
                const gp = navigator.getGamepads()[gamepadIndex];
                if (gp && gp.vibrationActuator) {
                    // Gamepad API takes duration/magnitude, not pattern array natively like navigator.vibrate
                    // We simply play a rumble for the total duration of the pattern for visual feedback consistency
                    // Or iterate. For simplicity in this demo, we play a generic effect for the first duration.
                    const firstDuration = Array.isArray(pattern) ? pattern[0] : pattern;
                    gp.vibrationActuator.playEffect("dual-rumble", {
                        startDelay: 0,
                        duration: firstDuration,
                        weakMagnitude: 1.0,
                        strongMagnitude: 1.0
                    });
                }
            }
            // Visuals
            const totalDuration = Array.isArray(pattern) ? pattern.reduce((a, b) => a + b, 0) : pattern;
            animateVisual(Array.isArray(pattern) ? pattern[0] : pattern); // Animate for first pulse
        }
        function setPattern(patternArr) {
            const input = document.getElementById('pattern-input');
            input.value = patternArr.join(', ');
            playCustom();
        }
        function playCustom() {
            const input = document.getElementById('pattern-input').value;
            const pattern = input.split(',').map(n => parseInt(n.trim())).filter(n => !isNaN(n));
            if (pattern.length > 0) {
                vibrateLogic(pattern);
            } else {
                alert("Invalid pattern. Use format: 200, 100, 200");
            }
        }
        function runResolutionTest() {
            // Decreasing pulse duration to test LRA vs ERM start/stop capability
            const testPattern = [
                200, 200, // Reference
                100, 100,
                80, 80,
                60, 60,
                40, 40,
                20, 20,
                10, 10,
                5, 5
            ];
            // Visual feedback needs to handle the sequence
            let totalTime = 0;
            testPattern.forEach((p, i) => {
                setTimeout(() => {
                    // Only pulse visual on the vibration part (even indices)
                    if (i % 2 === 0) {
                        motorVisual.classList.add('active');
                    } else {
                        motorVisual.classList.remove('active');
                    }
                }, totalTime);
                totalTime += p;
            });
            setTimeout(() => {
                motorVisual.classList.remove('active');
                statusText.innerText = "TEST COMPLETE";
            }, totalTime);
            // Execute Physical Vibration
            if ("vibrate" in navigator) {
                navigator.vibrate(testPattern);
                statusText.innerText = "RUNNING RESOLUTION SWEEP...";
            }
            // Gamepad
            if (gamepadIndex !== null) {
                const gp = navigator.getGamepads()[gamepadIndex];
                if (gp && gp.vibrationActuator) {
                    // We must queue these manually for gamepads as playEffect doesn't take a complex array
                    let currentTime = 0;
                    testPattern.forEach((duration, index) => {
                        if (index % 2 === 0) { // Vibrate
                            setTimeout(() => {
                                gp.vibrationActuator.playEffect("dual-rumble", {
                                    duration: duration,
                                    weakMagnitude: 1.0,
                                    strongMagnitude: 1.0
                                });
                            }, currentTime);
                        }
                        currentTime += duration;
                    });
                }
            }
        }
        // --- SCROLL LOGIC ---
